-- =============================================================================
-- Arcadia — seed public.locations with 100 dummy arcade locations
--
-- 15 US states, random real cities, plausible zips. Phones use the 555 prefix
-- (reserved for fiction). Emails use the .example TLD (reserved by RFC 2606).
-- Both are safe — nothing real points back at anyone.
-- Run after migrations 0001-0004. Idempotent via TRUNCATE.
--
-- TRUNCATE ... RESTART IDENTITY CASCADE wipes any existing locations and
-- cascades to gamelist / reviews / user_liked_locations. The generator uses a
-- two-pass deterministic seed: the base 5 fields are byte-identical to the
-- previous seed, so location IDs remain stable across re-seeds.
-- =============================================================================

TRUNCATE TABLE public.locations RESTART IDENTITY CASCADE;

